// Get all active connections and emit one message per connection
// Each message carries its own connection config — no shared global state
const activeConnections = global.get("parat_bridge").connections.filter(c => c.active);

if (activeConnections.length === 0) {
    return null;
}

const messages = activeConnections.map(connection => {
    return { connection: connection };
});

return [messages];

const connection = msg.connection;

msg.headers = {
    "x-api-key": connection.wasos.api.key
};

msg.url = global.get("parat_bridge").base_urls.wasos
    + "/api/chat/messages/" + connection.wasos.chatroom_name + "?limit=5";

return msg;
